public class Versions {

  // Constants for version 2
  public static final String KAFKA_V2_JSON = "application/vnd.kafka.v2+json";
  // This is set < 1 because it is only the most-specific type if there isn't an embedded data type.
  public static final String KAFKA_V2_JSON_WEIGHTED = KAFKA_V2_JSON + "; qs=0.9";
  public static final String KAFKA_V2_JSON_BINARY = "application/vnd.kafka.binary.v2+json";
  public static final String KAFKA_V2_JSON_BINARY_WEIGHTED = KAFKA_V2_JSON_BINARY;
  // "LOW" weightings are used to permit using these for resources like consumer where it might
  // be convenient to always use the same type, but where their use should really be discouraged
  public static final String KAFKA_V2_JSON_BINARY_WEIGHTED_LOW = KAFKA_V2_JSON_BINARY + "; qs=0.1";
  public static final String KAFKA_V2_JSON_AVRO = "application/vnd.kafka.avro.v2+json";
  public static final String KAFKA_V2_JSON_AVRO_WEIGHTED_LOW = KAFKA_V2_JSON_AVRO + "; qs=0.1";

  public static final String KAFKA_V2_JSON_JSON = "application/vnd.kafka.json.v2+json";
  public static final String KAFKA_V2_JSON_JSON_WEIGHTED_LOW = KAFKA_V2_JSON_JSON + "; qs=0.1";

  public static final String KAFKA_V2_JSON_JSON_SCHEMA = "application/vnd.kafka.jsonschema.v2+json";
  public static final String KAFKA_V2_JSON_JSON_SCHEMA_WEIGHTED_LOW =
      KAFKA_V2_JSON_JSON_SCHEMA + "; qs=0.1";

  public static final String KAFKA_V2_JSON_PROTOBUF = "application/vnd.kafka.protobuf.v2+json";
  public static final String KAFKA_V2_JSON_PROTOBUF_WEIGHTED_LOW =
      KAFKA_V2_JSON_PROTOBUF + "; qs=0.1";

  // These are defaults that track the most recent API version. These should always be specified
  // anywhere the latest version is produced/consumed.
  public static final String JSON = "application/json";

  // This is a fallback for when no type is provided. You usually should not need this. It is
  // mostly useful if you have two resource methods for the same endpoints but different Accept
  // or Content-Types. Adding this to one of them makes it the default even if no content type
  // information was specified in the request headers.
  public static final String ANYTHING = "*/*";

  public static final List<String> PREFERRED_RESPONSE_TYPES =
      Arrays.asList(MediaType.APPLICATION_JSON, Versions.KAFKA_V2_JSON);

  // This type is completely generic and carries no actual information about the type of data,
  // but it is the default for request entities if no content type is specified. Well behaving
  // users of the API will always specify the content type, but ad hoc use may omit it. We treat
  // this as JSON since that's all we currently support.
  public static final String GENERIC_REQUEST = "application/octet-stream";
}

public interface BrokerManager {

  /**
   * Returns the list of Kafka {@link Broker Brokers} belonging to the {@link
   * io.confluent.kafkarest.entities.Cluster} with the given {@code clusterId}.
   */
  CompletableFuture<List<Broker>> listBrokers(String clusterId);

  /** Returns the Kafka {@link Broker} with the given {@code brokerId}. */
  CompletableFuture<Optional<Broker>> getBroker(String clusterId, int brokerId);

  /**
   * Returns the list of Kafka {@link Broker Brokers} belonging to the {@link
   * io.confluent.kafkarest.entities.Cluster} that this application is connected to.
   */
  CompletableFuture<List<Broker>> listLocalBrokers();
}

@AutoValue
public abstract class Broker {

  Broker() {}

  public abstract String getClusterId();

  public abstract int getBrokerId();

  @Nullable
  public abstract String getHost();

  @Nullable
  public abstract Integer getPort();

  @Nullable
  public abstract String getRack();

  public static Broker create(
      String clusterId,
      int brokerId,
      @Nullable String host,
      @Nullable Integer port,
      @Nullable String rack) {
    return new AutoValue_Broker(clusterId, brokerId, host, port, rack);
  }

  public static Broker fromNode(String clusterId, Node node) {
    return create(
        clusterId,
        node.id(),
        !node.host().equals("") ? node.host() : null,
        node.port() != -1 ? node.port() : null,
        node.rack());
  }

  public Node toNode() {
    return new Node(
        getBrokerId(),
        getHost() != null ? getHost() : "",
        getPort() != null ? getPort() : -1,
        getRack());
  }
}

public final class BrokerList {

  @NotNull @Nullable private final List<Integer> brokers;

  @JsonCreator
  public BrokerList(@JsonProperty("brokers") @Nullable List<Integer> brokers) {
    this.brokers = brokers;
  }

  @JsonProperty
  @Nullable
  public List<Integer> getBrokers() {
    return brokers;
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    BrokerList that = (BrokerList) o;
    return Objects.equals(brokers, that.brokers);
  }

  @Override
  public int hashCode() {
    return Objects.hash(brokers);
  }

  @Override
  public String toString() {
    return new StringJoiner(", ", BrokerList.class.getSimpleName() + "[", "]")
        .add("brokers=" + brokers)
        .toString();
  }
}

public final class AsyncResponses {

  private AsyncResponses() {}

  /** Resumes the given {@code asyncResponse} with the result of {@code entity}. */
  public static <T> void asyncResume(AsyncResponse asyncResponse, CompletableFuture<T> entity) {
    AsyncResponseBuilder.<T>from(Response.ok()).entity(entity).asyncResume(asyncResponse);
  }

  /** A analogous of {@link AsyncResponse} for {@link ResponseBuilder}. */
  public static final class AsyncResponseBuilder<T> {

    private final ResponseBuilder responseBuilder;

    @Nullable private CompletableFuture<? extends T> entityFuture;

    @Nullable private Annotation[] entityAnnotations;

    @Nullable private Function<? super T, Response.Status> statusFunction;

    private AsyncResponseBuilder(ResponseBuilder responseBuilder) {
      this.responseBuilder = responseBuilder.clone();
    }

    /**
     * Returns a new {@link AsyncResponseBuilder} that when resumed, will return a response built
     * from the given {@code responseBuilder}.
     */
    public static <T> AsyncResponseBuilder<T> from(ResponseBuilder responseBuilder) {
      return new AsyncResponseBuilder<>(responseBuilder);
    }

    /** See {@link ResponseBuilder#entity(Object)}. */
    public AsyncResponseBuilder<T> entity(CompletableFuture<? extends T> entity) {
      entityFuture = entity;
      return this;
    }

    /** See {@link ResponseBuilder#entity(Object, Annotation[])}. */
    public AsyncResponseBuilder<T> entity(
        CompletableFuture<? extends T> entity, Annotation[] annotations) {
      entityFuture = entity;
      entityAnnotations = Arrays.copyOf(annotations, annotations.length);
      return this;
    }

    /**
     * Sets a function used to determine the status of the response based on the actual entity
     * returned.
     *
     * <p>This function is only used if the request completes successfully. Otherwise, the status
     * will be determined by the container exception handlers.
     *
     * @see ResponseBuilder#status(Response.Status)
     */
    public AsyncResponseBuilder<T> status(Function<? super T, Response.Status> statusFunction) {
      this.statusFunction = statusFunction;
      return this;
    }

    /** Resumes this {@code AsyncResponseBuilder}. */
    public void asyncResume(AsyncResponse asyncResponse) {
      if (entityFuture == null) {
        throw new IllegalStateException();
      }

      entityFuture.whenComplete(
          (entity, exception) -> {
            if (exception == null) {
              if (statusFunction != null) {
                responseBuilder.status(statusFunction.apply(entity));
              }
              if (entityAnnotations != null) {
                asyncResponse.resume(responseBuilder.entity(entity, entityAnnotations).build());
              } else {
                asyncResponse.resume(responseBuilder.entity(entity).build());
              }
            } else if (exception instanceof CompletionException) {
              asyncResponse.resume(exception.getCause());
            } else {
              asyncResponse.resume(exception);
            }
          });
    }
  }
}

