    @PositiveOrZero @Nullable private Integer broker;

    @Nullable private Boolean leader;

    @Nullable private Boolean inSync;

    @JsonCreator
    private Replica(
        @JsonProperty("broker") @Nullable Integer broker,
        @JsonProperty("leader") @Nullable Boolean leader,
        @JsonProperty("in_sync") @Nullable Boolean inSync) {
      this.broker = broker;
      this.leader = leader;
