public final class GetTopicResponse {

  @NotEmpty @Nullable private final String name;

  @NotNull @Nullable private final Map<String, String> configs;

  @NotEmpty @Nullable private final List<GetPartitionResponse> partitions;

  @JsonCreator
  private GetTopicResponse(
      @JsonProperty("name") @Nullable String name,
      @JsonProperty("configs") @Nullable Map<String, String> configs,
      @JsonProperty("partitions") @Nullable List<GetPartitionResponse> partitions) {
    this.name = name;
    this.configs = configs;
    this.partitions = partitions;
  }

  @JsonProperty
  @Nullable
  public String getName() {
    return name;
  }

  @JsonProperty
  @Nullable
  public Map<String, String> getConfigs() {
    return configs;
  }

  @JsonProperty
  @Nullable
  public List<GetPartitionResponse> getPartitions() {
    return partitions;
  }

  public static GetTopicResponse fromTopic(Topic topic, List<TopicConfig> configs) {
    HashMap<String, String> configsMap = new HashMap<>();
    for (TopicConfig config : configs) {
      configsMap.put(config.getName(), config.getValue());
    }
    return new GetTopicResponse(
        topic.getName(),
        configsMap,
        topic.getPartitions().stream()
            .map(GetPartitionResponse::fromPartition)
            .collect(Collectors.toList()));
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    GetTopicResponse that = (GetTopicResponse) o;
    return Objects.equals(name, that.name)
        && Objects.equals(configs, that.configs)
        && Objects.equals(partitions, that.partitions);
  }

  @Override
  public int hashCode() {
    return Objects.hash(name, configs, partitions);
  }

  @Override
  public String toString() {
    return new StringJoiner(", ", GetTopicResponse.class.getSimpleName() + "[", "]")
        .add("name='" + name + "'")
        .add("configs=" + configs)
        .add("partitions=" + partitions)
        .toString();
  }
}

public final class AsyncResponses {

  private AsyncResponses() {}

  /** Resumes the given {@code asyncResponse} with the result of {@code entity}. */
  public static <T> void asyncResume(AsyncResponse asyncResponse, CompletableFuture<T> entity) {
    AsyncResponseBuilder.<T>from(Response.ok()).entity(entity).asyncResume(asyncResponse);
