public final class TopicPartition {

  @NotEmpty @Nullable private final String topic;

  @PositiveOrZero @Nullable private final Integer partition;

  public TopicPartition(
      @JsonProperty("topic") @Nullable String topic,
      @JsonProperty("partition") @Nullable Integer partition) {
    this.topic = topic;
    this.partition = partition;
  }

  @JsonProperty
  @Nullable
  public String getTopic() {
    return topic;
  }

  @JsonProperty
  @Nullable
  public Integer getPartition() {
    return partition;
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    TopicPartition that = (TopicPartition) o;
    return Objects.equals(topic, that.topic) && Objects.equals(partition, that.partition);
  }

  @Override
  public int hashCode() {
    return Objects.hash(topic, partition);
  }

  @Override
  public String toString() {
    return new StringJoiner(", ", TopicPartition.class.getSimpleName() + "[", "]")
        .add("topic='" + topic + "'")
        .add("partition=" + partition)
        .toString();
  }
}
